/**
 * The approved legal wording changes of 2026-11-21 that land in the PUBLISHED answers' prose sections
 * (stageAnswers.published.json: "What is happening", "What to do next", "What happens after"), as data.
 *
 * One entry per change (Part 3 of "CourtSimplified: approved legal wording changes (from the legal review,
 * 2026-11-21)"). `text` is the approved text, word for word. `kind`:
 *   - "replace": `target` (the current text) becomes `text`;
 *   - "after":   `text` is added right after `target` (an anchor sentence that stays);
 *   - "end":     `text` is added at the end of the section;
 *   - "cite":    the wording is unchanged and only the sentence `target`'s supporting quote changes.
 * `quotes` are the passages of the saved official text each new sentence rests on; each must be found word for word
 * in the named saved source (docs/sources/corpus/<sourceId>.txt).
 *
 * "Your deadline" changes and the rules-only pages are not here: they are made at their one source, the stage map
 * (stageMap.ts, civilStages.ts, familyStages.ts, citations.ts), and checked by verifyLegalChanges20261121.ts from it.
 */

export type ProseSection = "whatsHappening" | "whatToDoNext" | "whatHappensAfter";
export type Quote = { sourceId: string; quote: string };
export type ProseChange = {
  n: number;
  stages: string[];
  section: ProseSection;
  kind: "replace" | "after" | "end" | "cite";
  target?: string;
  text: string;
  quotes: Quote[];
};

