/**
 * Change 125 (site-wide wording rule): the rule's own word, with the plain word in brackets for stay, suspend and
 * forthwith; "immediately" and "as soon as" as the rule says them. Meaning unchanged, so each new sentence carries the
 * quote its old sentence was already verified with (`quotes: []` = carry the old sentence's verified quote(s)).
 */
const w = (stage: string, section: ProseSection, target: string, text: string): ProseChange =>
  ({ n: 125, stages: [stage], section, kind: target ? "replace" : "end", target: target || undefined, text, quotes: [] });

